<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/bootstrap.php';
require_login();
require_once __DIR__ . '/includes/layout.php';
$error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') { try { verify_csrf(); $collection = request_value('collection'); restore_revision($collection, request_value('revision_file'), (int)request_value('collection_revision')); set_flash('success','تمت استعادة النسخة المختارة وإنشاء نسخة جديدة للحالة المستعادة.'); redirect_to('revisions.php?collection=' . rawurlencode($collection)); } catch (Throwable $e) { $error = $e->getMessage(); } }
$collection = request_value('collection','news'); if (!in_array($collection, allowed_collections(), true)) $collection = 'news';
$document = read_collection($collection); $revisions = list_revisions($collection);
admin_header('النسخ السابقة', 'استعادة آمنة تنشئ إصداراً جديداً ولا تمحو التاريخ'); if ($error !== ''): ?><div class="alert alert--error" role="alert"><?= e($error) ?></div><?php endif; ?>
<section class="panel"><div class="toolbar"><form method="get"><div class="field"><label for="collection">الوحدة</label><select id="collection" name="collection"><?php foreach (allowed_collections() as $value): ?><option value="<?= e($value) ?>" <?= $collection === $value ? 'selected' : '' ?>><?= e($value) ?></option><?php endforeach; ?></select></div><button class="btn btn--secondary" type="submit">عرض</button></form><span class="badge badge--published">الإصدار الحالي <?= (int)$document['_meta']['revision'] ?></span></div><?php if (!$revisions): ?><div class="empty-state">لا توجد نسخ محفوظة بعد.</div><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th>ملف النسخة</th><th>تاريخ الحفظ</th><th>الإجراء</th></tr></thead><tbody><?php foreach ($revisions as $file): ?><tr><td dir="ltr"><?= e($file) ?></td><td><?= e(date('d/m/Y H:i', filemtime(AMJAD_REVISION_DIR . '/' . $collection . '/' . $file))) ?></td><td><form method="post" data-confirm="استعادة هذه النسخة؟ ستُحفظ الحالة الحالية أيضاً في سجل الإصدارات."><?= csrf_field() ?><input type="hidden" name="collection" value="<?= e($collection) ?>"><input type="hidden" name="revision_file" value="<?= e($file) ?>"><input type="hidden" name="collection_revision" value="<?= (int)$document['_meta']['revision'] ?>"><button class="btn btn--secondary" type="submit">استعادة</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><?php admin_footer();
